export function buildOnboardingState(input) {
    const fields = Object.values(input);
    const invalid = fields.filter((field) => !['KNOWN', 'UNKNOWN', 'NEEDS_CONFIRMATION', 'NOT_APPLICABLE'].includes(field.state));
    if (invalid.length > 0) {
        return { ok: false, error: 'INVALID_KNOWLEDGE_STATE' };
    }
    const understanding = fields.map((field) => ({
        id: field.id,
        label: field.label,
        value: field.value,
        state: field.state,
        aiMayGuess: false
    }));
    return {
        ok: true,
        state: {
            mode: 'ONBOARDING',
            steps: [
                'WELCOME', 'CURRENT_SITUATION', 'ROLE', 'TOP_CONCERNS', 'BOSS_REPORTING', 'TEAM', 'PROJECTS',
                '30_DAY_GOAL', 'AI_UNDERSTANDING', '30_DAY_PLAN', 'DAY_1_TODAY', 'FIRST_SKILL'
            ],
            understanding,
            understandingConfirmed: false,
            phases: ONBOARDING_PHASES,
            timeToFirstUsefulTodayReady: understanding.some((field) => field.state === 'KNOWN')
        }
    };
}
export function confirmOnboardingUnderstanding(state, reviewer) {
    if (reviewer.type !== 'HUMAN' || !reviewer.id) {
        return { ok: false, error: 'HUMAN_CONFIRMATION_REQUIRED' };
    }
    return { ok: true, state: { ...state, understandingConfirmed: true, confirmedBy: { type: 'HUMAN', id: reviewer.id } } };
}

