export function getLeadershipQuest(day) {
    return LEADERSHIP_QUESTS.find((quest) => quest.day === Number(day)) ?? null;
}
export function questProgressSummary(completedDays = []) {
    const completed = new Set((Array.isArray(completedDays) ? completedDays : []).map(Number));
    const total = LEADERSHIP_QUESTS.length;
    const done = LEADERSHIP_QUESTS.filter((quest) => completed.has(quest.day)).length;
    return { total, done, percent: total ? Math.round((done / total) * 100) : 0 };
}

export function isRealFirstUse(pack) {
    if (!pack)
        return true;
    const items = [...pack.truth, ...pack.operational, ...pack.candidates, ...pack.recommendations];
    const meaningful = new Set(['PERSON', 'PROJECT', 'ACTION', 'COMMITMENT', 'MEETING', 'DECISION']);
    return !items.some((item) => meaningful.has(item.objectType));
}
export function parseFirstUseMembers(raw) {
    const seen = new Set();
    return raw.split(/\r?\n/).flatMap((line) => {
        const trimmed = line.trim();
        if (!trimmed)
            return [];
        const [rawName, ...roleParts] = trimmed.split(',');
        const name = rawName?.trim() ?? '';
        if (!name)
            return [];
        const key = name.toLocaleLowerCase();
        if (seen.has(key))
            return [];
        seen.add(key);
        const role = roleParts.join(',').trim();
        return [{ name, role: role || null }];
    });
}
export function parseFirstUseTasks(raw) {
    const seen = new Set();
    return raw.split(/\r?\n/).flatMap((line) => {
        const title = line.trim().replace(/^[-•]\s*/, '');
        if (!title)
            return [];
        const key = title.toLocaleLowerCase();
        if (seen.has(key))
            return [];
        seen.add(key);
        return [{ title }];
    });
}
